import os
from typing import Optional

import dashscope
from dashscope import MultiModalConversation


def describe_image(image_url: str, api_key: Optional[str] = None) -> str:
    key = api_key or os.environ.get("DASHSCOPE_API_KEY")
    if not key:
        raise ValueError("Missing DashScope API key. Set DASHSCOPE_API_KEY or pass api_key.")

    dashscope.api_key = key

    response = MultiModalConversation.call(
        model="qwen-vl-max",
        messages=[
            {
                "role": "system",
                "content": [{"text": "You are a vision assistant. Describe the image in one short sentence."}],
            },
            {
                "role": "user",
                "content": [
                    {"image": image_url},
                    {"text": "Provide a short visual description of this image."},
                ],
            },
        ],
    )

    if getattr(response, "status_code", None) != 200:
        message = getattr(response, "message", None) or str(response)
        raise RuntimeError(f"DashScope request failed: {message}")

    output = getattr(response, "output", None)
    if not output:
        raise RuntimeError("DashScope returned no output.")

    choices = output.get("choices") if isinstance(output, dict) else getattr(output, "choices", None)
    if not choices:
        raise RuntimeError("DashScope returned no choices.")

    message = choices[0].get("message", {})
    content = message.get("content", [])

    parts = []
    for item in content:
        if isinstance(item, dict):
            text = item.get("text")
            if text:
                parts.append(text)

    description = " ".join(parts).strip()
    if not description:
        raise RuntimeError("No textual description found in DashScope response.")

    return description
